<div class="page-title clearfix"><h1>Test Delivery</h1><a class="btn btn-default float-end" href="<?php echo site_url('email_marketing/audit'); ?>">Back to Audit</a></div>
<div class="alert alert-warning"><strong>TEST EMAIL ONLY.</strong> Test mode is <?php echo $test_mode ? 'enabled' : 'not enabled'; ?>. This page permits one message at a time and only to an approved, opted-in, active, non-suppressed, non-Do-Not-Contact CRM contact.</div>
<?php if (!$mail_configured): ?><div class="alert alert-danger">CRM email transport is not configured. No send is available.</div><?php endif; ?>
<div class="card"><div class="card-body"><form method="get" action="<?php echo site_url('email_marketing/test-delivery'); ?>"><div class="row"><div class="col-md-5"><label>Template</label><select class="form-control" name="template_id" required><option value="">Select a template</option><?php foreach ($templates as $item): ?><option value="<?php echo (int) $item->id; ?>" <?php echo $template && (int) $template->id === (int) $item->id ? 'selected' : ''; ?>><?php echo esc($item->name . ' — ' . $item->subject); ?></option><?php endforeach; ?></select></div><div class="col-md-5"><label>Approved test recipient</label><select class="form-control" name="contact_id" required><option value="">Select a recipient</option><?php foreach ($contacts as $item): ?><option value="<?php echo (int) $item->id; ?>" <?php echo $contact && (int) $contact->id === (int) $item->id ? 'selected' : ''; ?>><?php echo esc(trim($item->first_name . ' ' . $item->last_name) . ' — ' . $item->email); ?></option><?php endforeach; ?></select></div><div class="col-md-2"><label>&nbsp;</label><button class="btn btn-default form-control">Preview</button></div></div></form><p class="mt15">Approved addresses configured: <?php echo count($approved_emails); ?> (values hidden).</p></div></div>
<?php if ($template && $contact): ?><div class="card"><div class="card-body"><h3>Rendered preview</h3><p><strong>TEST EMAIL recipient:</strong> <?php echo esc($contact->email); ?></p><p><strong>Subject:</strong> <?php echo esc($preview_subject); ?></p><div class="well" style="background:#fff;border:1px solid #ddd;padding:15px;"><?php echo $preview_html; ?></div><form method="post" action="<?php echo site_url('email_marketing/test-delivery/send'); ?>" onsubmit="return confirm('Send exactly one TEST EMAIL to this approved recipient?');"><input type="hidden" name="<?php echo csrf_token(); ?>" value="<?php echo csrf_hash(); ?>"><input type="hidden" name="template_id" value="<?php echo (int) $template->id; ?>"><input type="hidden" name="contact_id" value="<?php echo (int) $contact->id; ?>"><button class="btn btn-warning" <?php echo (!$test_mode || !$mail_configured) ? 'disabled' : ''; ?>>Send one TEST EMAIL</button></form></div></div><?php endif; ?>
